import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_layer_norm_kernel(
    float const* x,
    float const* weight,
    float const* bias,
    float* y,
    int64_t rows,
    int64_t cols,
    float eps)
{
    int tid = threadIdx.x;
    __shared__ float reduction[32];
    const bool use_vec4 =
        ((cols & 3) == 0) &&
        ((((unsigned long long)x) & 15ULL) == 0ULL) &&
        ((((unsigned long long)weight) & 15ULL) == 0ULL) &&
        ((((unsigned long long)bias) & 15ULL) == 0ULL) &&
        ((((unsigned long long)y) & 15ULL) == 0ULL);
    for (int64_t row = static_cast<int64_t>(blockIdx.x);
         row < rows;
         row += static_cast<int64_t>(gridDim.x)) {
    float sum = 0.0f;
    if (use_vec4) {
        int64_t vec_cols = cols >> 2;
        float const* row_x = x + row * cols;
        float4 const* x4 = reinterpret_cast<float4 const*>(row_x);
        for (int64_t i = tid; i < vec_cols; i += blockDim.x) {
            float4 v = x4[i];
            sum += v.x + v.y + v.z + v.w;
        }
    } else {
        float const* row_x = x + row * cols;
        for (int64_t col = tid; col < cols; col += blockDim.x) {
            sum += row_x[col];
        }
    }
    int lane = tid & 31;
    int warp = tid >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }
    if (lane == 0) {
        reduction[warp] = sum;
    }
    __syncthreads();
    if (warp == 0) {
        sum = (lane < 16) ? reduction[lane] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        if (lane == 0) {
            reduction[0] = sum;
        }
    }
    __syncthreads();
    float mean = reduction[0] / static_cast<float>(cols);
    float variance_sum = 0.0f;
    if (use_vec4) {
        int64_t vec_cols = cols >> 2;
        float const* row_x = x + row * cols;
        float4 const* x4 = reinterpret_cast<float4 const*>(row_x);
        for (int64_t i = tid; i < vec_cols; i += blockDim.x) {
            float4 v = x4[i];
            float dx0 = v.x - mean;
            float dx1 = v.y - mean;
            float dx2 = v.z - mean;
            float dx3 = v.w - mean;
            variance_sum += dx0 * dx0 + dx1 * dx1 + dx2 * dx2 + dx3 * dx3;
        }
    } else {
        float const* row_x = x + row * cols;
        for (int64_t col = tid; col < cols; col += blockDim.x) {
            float diff = row_x[col] - mean;
            variance_sum += diff * diff;
        }
    }
    int lane_var = tid & 31;
    int warp_var = tid >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        variance_sum += __shfl_down_sync(0xffffffff, variance_sum, offset);
    }
    if (lane_var == 0) {
        reduction[warp_var] = variance_sum;
    }
    __syncthreads();
    if (warp_var == 0) {
        variance_sum = (lane_var < 16) ? reduction[lane_var] : 0.0f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            variance_sum += __shfl_down_sync(0xffffffff, variance_sum, offset);
        }
        if (lane_var == 0) {
            reduction[0] = variance_sum;
        }
    }
    __syncthreads();
    float variance = reduction[0] / static_cast<float>(cols);
    float inv_std = rsqrtf(variance + eps);
    if (use_vec4) {
        int64_t vec_cols = cols >> 2;
        float const* row_x = x + row * cols;
        float* row_y = y + row * cols;
        float4 const* x4 = reinterpret_cast<float4 const*>(row_x);
        float4* y4 = reinterpret_cast<float4*>(row_y);
        float4 const* w4 = reinterpret_cast<float4 const*>(weight);
        float4 const* b4 = reinterpret_cast<float4 const*>(bias);
        for (int64_t i = tid; i < vec_cols; i += blockDim.x) {
            float4 xv = x4[i];
            float4 wv = w4[i];
            float4 bv = b4[i];
            float4 out;
            out.x = (xv.x - mean) * inv_std * wv.x + bv.x;
            out.y = (xv.y - mean) * inv_std * wv.y + bv.y;
            out.z = (xv.z - mean) * inv_std * wv.z + bv.z;
            out.w = (xv.w - mean) * inv_std * wv.w + bv.w;
            y4[i] = out;
        }
    } else {
        float const* row_x = x + row * cols;
        float* row_y = y + row * cols;
        for (int64_t col = tid; col < cols; col += blockDim.x) {
            float normalized = (row_x[col] - mean) * inv_std;
            row_y[col] = normalized * weight[col] + bias[col];
        }
    }
    }
}


torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(),
                "weight and bias must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat,
                "x must have dtype float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat &&
                bias.scalar_type() == at::kFloat,
                "weight and bias must have dtype float32");
    TORCH_CHECK(x.dim() >= 3, "x must have at least three dimensions");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous(),
                "weight and bias must be contiguous");

    int64_t cols = x.size(x.dim() - 3) *
                   x.size(x.dim() - 2) *
                   x.size(x.dim() - 1);

    int64_t rows = x.numel() / cols;

    TORCH_CHECK(weight.numel() == cols,
                "weight must contain one value per normalized element");
    TORCH_CHECK(bias.numel() == cols,
                "bias must contain one value per normalized element");

    auto y = torch::empty_like(x);

    dim3 block(512);
    int64_t grid_rows = rows > 0 ? (rows < 4096 ? rows : 4096) : 1;
    dim3 grid(static_cast<unsigned int>(grid_rows));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_layer_norm_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        rows,
        cols,
        static_cast<float>(eps));

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE layer normalization kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_layer_norm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layer_norm"],
    extra_cflags=[
        "-O3",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()

        self.normalized_shape = tuple(normalized_shape)
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layer_norm(
            x,
            self.weight,
            self.bias,
            self.eps,
        )

